WITH latest_match AS (SELECT s.id, s.started_at, top1.page, top1.duration_sec FROM sessions s JOIN LATERAL (SELECT c.page, c.duration_sec FROM web_events c WHERE c.session_id = s.id ORDER BY c.event_time DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT DATE_TRUNC('YEAR', started_at) AS year_start, page, COUNT(*) AS cnt, COUNT(CASE WHEN page = '/search' THEN 1 END) AS search_count, COUNT(*) AS cnt_2 FROM latest_match GROUP BY ROLLUP (DATE_TRUNC('YEAR', started_at), page)
